1	import { Client } from "@colyseus/sdk";
2	import { matchMaker } from "colyseus";
3	import { afterAll, afterEach, beforeAll, describe, expect, it } from "vitest";
4	import {
5	  DUEL_CODE_REQUIRED_MESSAGE,
6	  DUEL_COUNTDOWN_FRAMES,
7	  DUEL_ROOM,
8	  duelFullMessage,
9	  DuelMessageType,
10	  INPUT_HOLD_FRAMES,
11	  MALFORMED_MATCH_REQUEST_MESSAGE,
12	  NO_SUCH_DUEL_MESSAGE,
13	  PROTOCOL_VERSION,
14	  type DuelFrameBundle,
15	} from "@pirate-sea-race/protocol";
16	import { DuelRoom, startGameServer, type RunningGameServer } from "@pirate-sea-race/server";
17	import { duelInput, hashState } from "@pirate-sea-race/simulation/duel";
18	import { MAX_INPUT_DELAY, MIN_INPUT_DELAY } from "@pirate-sea-race/simulation/netcode";
19	import { HeadlessDuelClient, ImpairmentProxy, newCreateToken, replayRecordedDuel, sleep } from "@pirate-sea-race/test-tools";
20	
21	let server: RunningGameServer;
22	let endpoint: string;
23	const clients: HeadlessDuelClient[] = [];
24	const proxies: ImpairmentProxy[] = [];
25	
26	const R = duelInput("right");
27	const J = duelInput("light");
28	const K = duelInput("heavy");
29	
30	async function track(client: Promise<HeadlessDuelClient>): Promise<HeadlessDuelClient> {
31	  const joined = await client;
32	  clients.push(joined);
33	  return joined;
34	}
35	
36	function roomOf(client: HeadlessDuelClient): DuelRoom {
37	  return matchMaker.getLocalRoomById(client.room.roomId) as unknown as DuelRoom;
38	}
39	
40	/** The refusal a request ends with; fails the test if the request succeeds. */
41	async function refusal(attempt: Promise<unknown>): Promise<{ code: unknown; message: string }> {
42	  const error: unknown = await attempt.then(
43	    () => expect.fail("the request was admitted"),
44	    (reason: unknown) => reason,
45	  );
46	  return { code: (error as { code?: unknown }).code, message: (error as Error).message };
47	}
48	
49	/** The pairs the server applied, by frame, from the bundles a client received. */
50	function appliedPairs(bundles: readonly DuelFrameBundle[]): Map<number, { pair: readonly [number, number]; substituted: [boolean, boolean] }> {
51	  const pairs = new Map<number, { pair: readonly [number, number]; substituted: [boolean, boolean] }>();
52	  for (const bundle of bundles) {
53	    const first = bundle.frame - bundle.inputs.length + 1;
54	    bundle.inputs.forEach((pair, index) => {
55	      pairs.set(first + index, { pair, substituted: [((bundle.substituted >> (2 * index)) & 1) === 1, ((bundle.substituted >> (2 * index + 1)) & 1) === 1] });
56	    });
57	  }
58	  return pairs;
59	}
60	
61	/** The newest frame the server has confirmed to this client. */
62	const latestFrame = (client: HeadlessDuelClient) => client.bundles.at(-1)?.frame ?? -1;
63	
64	/**
65	 * Plays a frame-exact timeline of inputs, `inputs[k]` for frame `start + k`, as raw input messages of four frames
66	 * each, sent 6 to 25 frames ahead of the server (the session's own sending is off). This is how the tests press
67	 * keys a precise number of frames apart; the browser and the session send the same messages.
68	 */
69	async function playTimeline(client: HeadlessDuelClient, start: number, inputs: readonly number[]): Promise<void> {
70	  let seq = 1000;
71	  for (let offset = 0; offset < inputs.length; offset += 4) {
72	    const first = start + offset;
73	    const chunk = inputs.slice(offset, offset + 4);
74	    await client.waitFor(() => latestFrame(client) >= first + chunk.length - 1 - 25);
75	    if (latestFrame(client) > first - 6) throw new Error(`the timeline fell behind the server at frame ${first}`);
76	    client.sendRaw(DuelMessageType.Input, { seq: ++seq, frame: first + chunk.length - 1, inputs: chunk });
77	  }
78	}
79	
80	const hold = (frames: number, bits = 0) => Array.from({ length: frames }, () => bits);
81	
82	beforeAll(async () => {
83	  server = await startGameServer({ port: 0, host: "127.0.0.1", handleSignals: false });
84	  endpoint = `http://127.0.0.1:${server.port}`;
85	});
86	
87	afterEach(async () => {
88	  await Promise.all(clients.splice(0).map((client) => client.leave()));
89	  await Promise.all(proxies.splice(0).map((proxy) => proxy.close()));
90	});
91	
92	afterAll(async () => {
93	  await server.close();
94	});
95	
96	describe("duel admission", { timeout: 30_000 }, () => {
97	  it("admits the creator by token and the second player by code, and nobody else", async () => {
98	    const host = await track(HeadlessDuelClient.create(endpoint));
99	    expect(host.code).toMatch(/^[A-Z0-9]{6}$/);
100	    expect(host.slot).toBe(0);
101	    expect(host.phase).toBe("waiting");
102	    const version = { protocolVersion: PROTOCOL_VERSION };
103	    expect(await refusal(new Client(endpoint).join(DUEL_ROOM, { ...version, code: host.code === "ZZZZZ9" ? "ZZZZZ8" : "ZZZZZ9" }))).toEqual({
104	      code: 404,
105	      message: NO_SUCH_DUEL_MESSAGE,
106	    });
107	    expect(await refusal(new Client(endpoint).join(DUEL_ROOM, version))).toEqual({ code: 400, message: MALFORMED_MATCH_REQUEST_MESSAGE });
108	    expect(await refusal(new Client(endpoint).joinById(host.room.roomId, { ...version, createToken: newCreateToken() }))).toEqual({
109	      code: 403,
110	      message: DUEL_CODE_REQUIRED_MESSAGE,
111	    });
112	    expect(await refusal(new Client(endpoint).join(DUEL_ROOM, { protocolVersion: PROTOCOL_VERSION - 1, code: host.code }))).toMatchObject({ code: 426 });
113	
114	    const guest = await track(HeadlessDuelClient.join(endpoint, host.code.toLowerCase()));
115	    expect(guest.room.roomId).toBe(host.room.roomId);
116	    expect(guest.slot).toBe(1);
117	    expect(await refusal(new Client(endpoint).join(DUEL_ROOM, { ...version, code: host.code }))).toEqual({ code: 409, message: duelFullMessage() });
118	    expect(await refusal(new Client(endpoint).joinById(host.room.roomId, { ...version, code: host.code }))).toMatchObject({ code: expect.anything() });
119	    expect(roomOf(host).clients.length).toBe(2);
120	  });
121	
122	  it("holds one player in a practice duel", async () => {
123	    const player = await track(HeadlessDuelClient.create(endpoint, { practice: true }));
124	    expect(player.room.state.practice).toBe(true);
125	    expect(player.room.state.dummy).toBe("idle");
126	    expect(await refusal(new Client(endpoint).join(DUEL_ROOM, { protocolVersion: PROTOCOL_VERSION, code: player.code }))).toMatchObject({ code: 409 });
127	  });
128	});
129	
130	describe("duel room", { timeout: 30_000 }, () => {
131	  it("counts down three seconds once both are connected, then fights with a shared input delay of 3 to 8 frames", async () => {
132	    const host = await track(HeadlessDuelClient.create(endpoint));
133	    await sleep(300);
