5	  CATCH_UP_FRAMES,
6	  chooseInputDelay,
7	  DuelAuthority,
8	  DuelClientSession,
9	  DuelClock,
10	  DuelEventFeed,
11	  DuelRollback,
12	  duelEventId,
13	  FRAME_MS,
14	  HELD_INPUT_FRAMES,
15	  HISTORY_FRAMES,
16	  INPUTS_PER_MESSAGE,
17	  linkStats,
18	  MAX_INPUT_DELAY,
19	  MESSAGES_PER_SECOND,
20	  MIN_INPUT_DELAY,
21	  RESYNC_FRAMES,
22	  type AuthorityBundle,
23	  type OutgoingDuelInput,
24	} from "./index.js";
25	
26	const { fighter: body, arena } = config.moveset;
27	const R = I("right");
28	const L = I("left");
