39	/** What each player holds at a client frame (before the input delay). */
40	type Script = (clientFrame: number) => number;
41	
42	interface NetworkResult {
43	  readonly authority: DuelAuthority;
44	  readonly clients: readonly [DuelRollback, DuelRollback];
45	}
46	
47	/**
48	 * A lockstep model of the duel network in whole frames: both clients run on the server's frame, tag the input held
49	 * at frame c for c + delay, send the last four tagged frames every second frame, and the messages and bundles arrive
50	 * `up` and `down` frames later. Everything is deterministic, so exact counts can be asserted.
51	 */
52	function network(options: { initial: DuelState; delay: number; up: number; down: number; frames: number; scripts: readonly [Script, Script] }): NetworkResult {
53	  const authority = new DuelAuthority(config, options.initial);
54	  const clients = [new DuelRollback(config, 0, options.initial), new DuelRollback(config, 1, options.initial)] as const;
55	  const toServer: { at: number; player: PlayerIndex; message: OutgoingDuelInput }[] = [];
56	  const toClients: { at: number; bundle: AuthorityBundle }[] = [{ at: options.down, bundle: authority.snapshotBundle() }];
57	  const seq = [0, 0];
58	  // During the countdown each client tagged and sent the first frames of the fight, with nothing held.
59	  for (const player of [0, 1] as const) {
60	    for (let early = 1; early < options.delay; early++) clients[player].setLocalInput(early, 0);
61	    for (let last = 2; last < options.delay + 1; last += 2) {
62	      const frame = Math.min(last, options.delay - 1);
63	      const inputs = Array.from({ length: Math.min(4, frame) }, () => 0);
64	      toServer.push({ at: 0, player, message: { seq: ++seq[player]!, frame, inputs } });
65	    }
66	  }
67	  for (let frame = 1; frame <= options.frames; frame++) {
68	    // Clients: tag and send, as of the previous frame (the one they are on when the server steps this one).
69	    for (const player of [0, 1] as const) {
70	      const client = clients[player];
71	      const tagged = frame - 1 + options.delay;
72	      client.setLocalInput(tagged, options.scripts[player](frame - 1));
73	      if (frame % 2 === 1) {
74	        const first = Math.max(1, tagged - 3);
75	        const inputs = Array.from({ length: tagged - first + 1 }, (_, index) => client.localInput(first + index) ?? 0);
76	        toServer.push({ at: frame + options.up, player, message: { seq: ++seq[player]!, frame: tagged, inputs } });
77	      }
78	    }
79	    // Server: the messages due, then the step.
80	    for (const item of toServer.filter((entry) => entry.at <= frame)) authority.receive(item.player, item.message.frame, item.message.inputs);
81	    toServer.splice(0, toServer.filter((entry) => entry.at <= frame).length);
82	    const bundle = authority.step();
83	    if (bundle !== undefined) toClients.push({ at: frame + options.down, bundle });
84	    // Clients: the bundles due, then predict up to this frame.
85	    const due = toClients.filter((entry) => entry.at <= frame);
86	    toClients.splice(0, due.length);
87	    for (const client of clients) {
88	      for (const entry of due) client.applyBundle(entry.bundle);
89	      client.stepTo(frame);
90	    }
91	  }
92	  // Drain the network so every frame is confirmed.
93	  for (const client of clients) for (const entry of toClients) client.applyBundle(entry.bundle);
94	  return { authority, clients };
95	}
