350	/** A client session driven by a fake clock at an exact 60 Hz, with the server's probes and bundles fed in. */
351	function sessionRig(options: { player?: PlayerIndex; initial?: DuelState; delay?: number } = {}) {
352	  const initial = options.initial ?? closeDuel(40);
353	  const session = new DuelClientSession({ config, player: options.player ?? 0, initial });
354	  session.inputDelay = options.delay ?? 3;
355	  // The server's frame 0 is at local time 1000 and the link is instant: messages arrive on a frame's edge, and the
356	  // client ticks in the middle of a frame.
357	  const edge = (frame: number) => 1000 + frame * FRAME_MS;
358	  const at = (frame: number) => edge(frame) + FRAME_MS / 2;
359	  session.receiveProbe({ frame: -60, rtt: 0 }, edge(-60));
360	  const sent: OutgoingDuelInput[] = [];
361	  const sentAt: number[] = [];
362	  const tick = (now: number, bits: number) => {
363	    const message = session.tick(now, bits);
364	    if (message === undefined) return;
365	    sent.push(message);
366	    sentAt.push(now);
367	  };
368	  return { session, sent, sentAt, at, edge, tick, initial };
369	}
